import { readFileSync, writeFileSync } from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const manifestPath = path.join(root, 'assets', 'fonts', 'manifest.json');
const outPath = path.join(root, 'src', 'renderer', 'editor', 'layout', 'bundled-fonts.css');

const manifest = JSON.parse(readFileSync(manifestPath, 'utf8'));

const lines = [
  '/* Generated by scripts/generate-page-font-css.mjs. Do not edit by hand. */',
  '/* Bundled fonts live under assets/fonts and are served from /fonts. */',
  '',
];

for (const face of manifest.faces) {
  const family = face.family.replace(/\\/g, '\\\\').replace(/"/g, '\\"');
  lines.push('@font-face {');
  lines.push(`  font-family: "${family}";`);
  lines.push(`  font-style: ${face.style};`);
  lines.push(`  font-weight: ${face.weight};`);
  lines.push('  font-display: block;');
  lines.push(`  src: url("/fonts/${face.file}") format("truetype");`);
  lines.push('}');
  lines.push('');
}

writeFileSync(outPath, `${lines.join('\n')}\n`, 'utf8');
console.log(`Wrote ${path.relative(root, outPath)} (${manifest.faces.length} faces)`);